package dev.irisvisualizer.editor;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.function.Function;

/** Ordered procedural decorators, accent foliage and ruin accents; no geometry or selection runs. */
public final class ProceduralAccents {
    public static final List<String> TREE_FIELDS = List.of("decorators", "weightedSecondaryLeaves");
    public static final List<String> RUIN_FIELDS = List.of("accents");
    public static final List<String> DECORATOR_FIELDS = List.of("target", "block", "palette", "chance", "length", "axisAware");
    public static final List<String> LEAF_FIELDS = List.of("block", "weight");
    public static final List<String> ACCENT_FIELDS = List.of("target", "block", "palette", "chance", "scatterRadius");
    private static final Properties DATA=new Properties();
    static { try (var input=ProceduralAccents.class.getResourceAsStream("/procedural-accent-fields.properties")) { if (input==null) throw new IOException("Missing pinned procedural accent contracts");DATA.load(input);if (!"longSumNonnegative".equals(DATA.getProperty("weight.policy")) || !"secondaryPaletteThenWeightedThenSingle".equals(DATA.getProperty("secondary.policy"))) throw new IOException("Unsupported accent selection policy"); } catch (IOException failure) { throw new ExceptionInInitializerError(failure); } }
    public static List<String> lists(String kind) { if (kind==null || !ProceduralObjects.LIST_FIELDS.contains(kind)) throw new IllegalArgumentException("Select a procedural kind");return kind.equals("trees") ? TREE_FIELDS : kind.equals("ruins") ? RUIN_FIELDS : List.of(); }
    private static void list(ProceduralObjects.Context owner,String list) { if (owner==null || list==null || !lists(owner.kind()).contains(list)) throw new IllegalArgumentException("Select a supported procedural accent collection"); }
    public record Context(ProceduralObjects.Context owner,String list,int index) {
        public Context { ProceduralAccents.list(owner,list);if (index<0) throw new IllegalArgumentException("Select an accent entry"); }
        public String prefix() { return listPrefix(owner,list)+index+"."; }
        public boolean palette() { return !list.equals("weightedSecondaryLeaves"); }
        public ProceduralMaterials.Context paletteContext() { if (!palette()) throw new IllegalArgumentException("Weighted foliage has no palette member");return ProceduralMaterials.Context.accent(this); }
    }
    public static String listPrefix(ProceduralObjects.Context owner,String list) { list(owner,list);return owner.prefix()+list+"."; }
    private static void authorize(String path,Context c) { if (c==null) throw new IllegalArgumentException("Select an accent context");ProceduralObjects.authorize(path,c.owner()); }
    public static List<String> fields(Context c) { return c.list().equals("decorators") ? DECORATOR_FIELDS : c.list().equals("accents") ? ACCENT_FIELDS : LEAF_FIELDS; }
    public static List<String> scalars(Context c) { return fields(c).stream().filter(f -> !f.equals("palette")).toList(); }
    private static void field(Context c,String field) { if (field==null || !fields(c).contains(field)) throw new IllegalArgumentException("Select an accent field"); }
    private static void scalar(Context c,String field) { field(c,field);if (field.equals("palette")) throw new IllegalArgumentException("Use palette controls"); }
    public static String help(Context c,String field) { field(c,field);return DATA.getProperty(c.list()+"."+field+".description"); }
    static String property(Context c,String field,String key) { field(c,field);return DATA.getProperty(c.list()+"."+field+"."+key); }
    public static String type(Context c,String field) { scalar(c,field);return property(c,field,"type"); }
    public static String defaultValue(Context c,String field) { scalar(c,field);return property(c,field,"default"); }
    public static List<String> choices(Context c,String field) { scalar(c,field);String values=property(c,field,"choices");return values==null ? List.of() : List.of(values.split(",")); }
    public static String choiceHelp(Context c,String field,String choice) { return property(c,field,choice+".description"); }
    public static String constraints(Context c,String field) { String min=property(c,field,"minimum"),max=property(c,field,"maximum");return (type(c,field).equals("int") ? "Exact signed 32-bit integer" : "Finite number")+(min==null ? "" : "; minimum "+min)+(max==null ? "" : "; maximum "+max); }
    static List<LosslessJson> entries(LosslessJson entry,String list) { if (list==null || !List.of("decorators","weightedSecondaryLeaves","accents").contains(list)) throw new IllegalArgumentException("Unknown accent list");String token=entry.token(list);return token==null || token.equals("null") ? null : entry.objectArray(list); }
    private static void limit(List<LosslessJson> rows,boolean adding) { if (rows!=null && (rows.size()>64 || adding && rows.size()>=64)) throw new IllegalArgumentException("Accent collections have a 64-entry editor limit"); }
    static LosslessJson entry(LosslessJson owner,Context c) { var rows=entries(owner,c.list());limit(rows,false);if (rows==null || c.index()>=rows.size()) throw new IllegalArgumentException("Select an existing accent entry");return rows.get(c.index()); }
    static byte[] edit(byte[] raw,Context c,Function<LosslessJson,byte[]> op) { return ProceduralObjects.edit(raw,c.owner(),owner -> { entry(owner,c);return owner.objectArrayEdit(c.list(),c.index(),op); }); }
    public static byte[] change(String path,byte[] raw,ProceduralObjects.Context owner,String list,RiverProfiles.Action action,int index,String block) { list(owner,list);ProceduralObjects.authorize(path,owner);if (action==null) throw new IllegalArgumentException("Choose an accent action");if (action==RiverProfiles.Action.ADD && !ProceduralMaterials.blockSyntax(block)) throw new IllegalArgumentException("Choose a nonblank Minecraft or unnamespaced block/alias");return ProceduralObjects.edit(raw,owner,o -> { var rows=entries(o,list);limit(rows,action==RiverProfiles.Action.ADD || action==RiverProfiles.Action.DUPLICATE);if (action==RiverProfiles.Action.ADD) { if (rows==null) o=new LosslessJson(o.enableArray(list));byte[] seed=new LosslessJson("{}".getBytes(StandardCharsets.UTF_8)).enableStringPath("block",block);return o.objectArrayInsert(list,rows==null ? 0 : rows.size(),seed); }if (rows==null || index<0 || index>=rows.size()) throw new IllegalArgumentException("Select an existing accent entry");if (action==RiverProfiles.Action.REMOVE && rows.size()==1) return o.removeField(list);return BiomeLayers.changeLayers(o,list,action,index); }); }
    public static byte[] resetList(String path,byte[] raw,ProceduralObjects.Context owner,String list) { list(owner,list);ProceduralObjects.authorize(path,owner);return ProceduralObjects.edit(raw,owner,o -> { limit(entries(o,list),false);return o.token(list)==null ? o.sourceBytes() : o.removeField(list); }); }
    static String value(LosslessJson entry,Context c,String field) { String type=type(c,field),token=entry.token(field);if (token==null) return defaultValue(c,field);if (type.equals("String")) return token.equals("null") ? "" : entry.stringToken(field);if (!choices(c,field).isEmpty()) return entry.stringToken(field);if (type.equals("boolean")) { if (!List.of("true","false").contains(token)) throw new IllegalArgumentException("Stored flag is not boolean");return token; }try { if (!LosslessJson.numericToken(token)) throw new NumberFormatException();var n=new BigDecimal(token);if (type.equals("int")) n.intValueExact();else if (!Double.isFinite(n.doubleValue())) throw new ArithmeticException();return token; } catch (NumberFormatException | ArithmeticException bad) { throw new IllegalArgumentException("Stored accent scalar has unsupported numeric type/width",bad); } }
    public static byte[] set(String path,byte[] raw,Context c,String field,String input) { authorize(path,c);scalar(c,field);if (input==null || input.indexOf(0)>=0) throw new IllegalArgumentException("Enter an accent value without NUL");String type=type(c,field);BigDecimal number=null;
        if (type.equals("String")) { if (!input.isEmpty() && !ProceduralMaterials.blockSyntax(input)) throw new IllegalArgumentException("Use empty, Minecraft or unnamespaced block/alias syntax"); }else if (!choices(c,field).isEmpty()) { if (!choices(c,field).contains(input)) throw new IllegalArgumentException("Choose a pinned accent target"); }else if (type.equals("boolean")) { if (!List.of("true","false").contains(input)) throw new IllegalArgumentException("Choose true or false"); }else { try { number=new BigDecimal(input);if (type.equals("int")) number.intValueExact();else if (!Double.isFinite(number.doubleValue()) || number.signum()!=0 && number.doubleValue()==0) throw new ArithmeticException(); } catch (NumberFormatException | ArithmeticException bad) { throw new IllegalArgumentException("Enter a finite value with native numeric width",bad); }String min=property(c,field,"minimum"),max=property(c,field,"maximum");if (min!=null && number.compareTo(new BigDecimal(min))<0 || max!=null && number.compareTo(new BigDecimal(max))>0) throw new IllegalArgumentException(constraints(c,field)); }
        BigDecimal desired=number;return edit(raw,c,o -> { String old=value(o,c,field);if (o.token(field)!=null && !o.token(field).equals("null") && (desired!=null ? desired.compareTo(new BigDecimal(old))==0 : old.equals(input))) return o.sourceBytes();if (desired!=null) return type.equals("int") ? o.nullableInteger(field,desired.longValueExact()) : o.token(field)==null ? o.enable(field,desired.toString()) : o.number(field,desired.doubleValue());if (type.equals("String") || !choices(c,field).isEmpty()) return o.nullableString(field,input);return o.token(field)==null ? o.enable(field,input) : o.bool(field,Boolean.parseBoolean(input)); });
    }
    public static byte[] resetLeaf(String path,byte[] raw,Context c,String field) { authorize(path,c);scalar(c,field);return edit(raw,c,o -> { value(o,c,field);return o.token(field)==null ? o.sourceBytes() : o.removeField(field); }); }
    static List<String> readOnlyPaths(LosslessJson owner,ProceduralObjects.Context placement,String list) { list(placement,list);var paths=new ArrayList<String>();try { var rows=entries(owner,list);limit(rows,false);if (rows!=null) for (int i=0;i<rows.size();i++) { var c=new Context(placement,list,i);for (String field : rows.get(i).fields()) { if (c.palette() && field.equals("palette")) paths.addAll(ProceduralMaterials.readOnlyPaths(owner,c.paletteContext()));else if (!scalars(c).contains(field)) paths.add(list+"["+i+"]."+field);else try { value(rows.get(i),c,field); } catch (IllegalArgumentException bad) { paths.add(list+"["+i+"]."+field); } } } } catch (IllegalArgumentException bad) { paths.add(list); }return List.copyOf(paths); }
}
